/bin/bash -lc "python -m pip install -q 'assemblyai==1.10.0' && python - <<'PY'
import urllib.request,json
urls=['https://assemblyai.com/docs/llms.txt','https://assemblyai.com/docs/llms-full.txt','https://raw.githubusercontent.com/AssemblyAI/assemblyai-python-sdk/master/MIGRATION.md']
for i,url in enumerate(urls):
 try:
  data=urllib.request.urlopen(url,timeout=20).read().decode();open('/tmp/aai-docs-'+str(i),'w').write(data);print(url,len(data));print(data[:1500])
 except Exception as e: print(url,e)
j=json.load(open('/tmp/assemblyai-pypi.json'))['info']['description']
a=j.find('### **LLM Gateway Examples**');print(j[a:a+15000])
PY"

