/bin/bash -lc "python - <<'PY'
import assemblyai as aai
models=aai.LLMGateway().models.list()
for m in models.data:
 if m.id in ['claude-sonnet-5','gpt-5-mini','gpt-4.1','gemini-2.5-flash','gpt-6-luna','claude-haiku-4-5-20251001']:print(m.dict())
for model in ['claude-sonnet-5','gpt-5-mini','gemini-2.5-flash','gpt-4.1']:
 try:
  r=aai.LLMGateway().chat.completions.create(model=model,messages=[{'role':'user','content':'Summarize in two sentences: The Quorvex dashboard ships Thursday. Talvanta moves to next sprint.'}],max_tokens=512)
  print(model,r);break
 except aai.LLMGatewayError as e:print(model,e.status_code,e.errors,str(e))
PY"

